import {pinVoltage,poweredDevice,logic} from './bus-electrical.js';
// All devices sample the previous DC solution before any output is changed.
export function attachShiftRuntime(runtime,engine,initial){let project=initial,states=new Map(),disposed=false,busy=false,key='';
 const refresh=()=>{if(disposed||busy)return;busy=true;try{const dc=engine.solution,drivers=[],adj=new Map();for(const b of dc.branches)for(const[a,c]of[[b.a,b.b],[b.b,b.a]]){if(!adj.has(a))adj.set(a,[]);adj.get(a).push(c);}const supply=(node,owners)=>{const seen=new Set([node]),queue=[node];for(let i=0;i<queue.length;i++){const at=queue[i];if(dc.known.has(at)&&dc.known.get(at)>=2){if(!String(at).startsWith('$driver:'))return true;const owner=String(at).split(':')[1];if(!states.has(owner))return true;if(!owners.has(owner)&&supply(dc.netlist.net(owner+':VCC'),new Set([...owners,owner])))return true;}for(const n of adj.get(at)||[])if(!seen.has(n)){seen.add(n);queue.push(n);}}return false;};for(const d of states.values()){const v=pin=>pinVoltage(dc,d.id,pin),p=poweredDevice(dc,d.id,{vcc:'VCC',gnd:'GND',min:2,max:6}),level=pin=>logic(v(pin),p.voltage);p.powered=p.powered&&supply(dc.netlist.net(d.id+':VCC'),new Set([d.id]));if(!p.powered){d.shift=0;d.latch=0;d.clock=null;d.latchClock=null;}Object.assign(d,p);const controls=d.type==='hc595'?['SER','SRCLK','RCLK','SRCLR','OE']:['SER','CLK','CE','PL'];d.overvoltage=controls.some(pin=>Number.isFinite(v(pin))&&(v(pin)>p.voltage+.3||v(pin)<-.3));const input=level('SER');d.connected=p.powered&&!d.overvoltage;const old=d.shift;
 if(d.type==='hc595'){const clk=level('SRCLK'),latch=level('RCLK'),clear=level('SRCLR'),oe=level('OE');d.connected=d.connected&&[clk,latch,clear,oe].every(b=>b!==null);if(d.connected){if(clear===false)d.shift=0;else if(clk===true&&d.clock===false){if(input!==null){d.shift=((old<<1)|(input?1:0))&255;d.clocks++;}else d.connected=false;}if(latch===true&&d.latchClock===false){d.latch=clear===false?0:old;d.loads++;}}d.enabled=d.connected&&oe===false;if(d.enabled)for(let i=0;i<8;i++)drivers.push({endpoint:d.id+':Q'+i,voltage:d.latch&(1<<i)?p.voltage:0,ohms:50});if(p.powered&&!d.overvoltage)drivers.push({endpoint:d.id+':Q7S',voltage:d.shift&128?p.voltage:0,ohms:50});d.clock=clk;d.latchClock=latch;
 }else{const pl=level('PL'),clk=level('CLK'),ce=level('CE'),gate=clk===null||ce===null?null:clk||ce;d.connected=d.connected&&pl!==null;if(d.connected&&pl===false){const data=Array.from({length:8},(_,i)=>level('D'+i));if(data.every(b=>b!==null)&&Array.from({length:8},(_,i)=>v('D'+i)).every(n=>n>=-.3&&n<=p.voltage+.3)){d.shift=data.reduce((a,b,i)=>a|(b?1<<i:0),0);if(d.pl!==false)d.loads++;}else d.connected=false;}else if(d.connected&&pl===true&&gate===true&&d.clock===false){if(input!==null){d.shift=((old<<1)|(input?1:0))&255;d.clocks++;}else d.connected=false;}if(p.powered&&!d.overvoltage){drivers.push({endpoint:d.id+':Q7',voltage:d.shift&128?p.voltage:0,ohms:50},{endpoint:d.id+':Q7N',voltage:d.shift&128?0:p.voltage,ohms:50});}d.clock=gate;d.pl=pl;}
 }const next=JSON.stringify(drivers);if(next!==key){key=next;engine.setDrivers('shift-register',drivers);}}finally{busy=false;}};
 const reconcile=()=>{const ids=new Set();for(const c of project.components.filter(c=>['hc595','hc165'].includes(c.type))){ids.add(c.id);if(!states.has(c.id))states.set(c.id,{id:c.id,type:c.type,shift:0,latch:0,clocks:0,loads:0,clock:null,latchClock:null,pl:null});}for(const id of states.keys())if(!ids.has(id))states.delete(id);refresh();};reconcile();const unsubscribe=engine.subscribe(refresh);return{updateProject(next){project=next;reconcile();},snapshot(){refresh();return{modules:Object.fromEntries([...states].map(([id,d])=>[id,{type:d.type,powered:d.powered,connected:d.connected,overvoltage:d.overvoltage,shift:d.shift,latch:d.latch,enabled:d.enabled,clocks:d.clocks,loads:d.loads}]))};},dispose(){disposed=true;unsubscribe();engine.setDrivers('shift-register',[]);}};
}
